import json, sys
def load(p):
    return json.load(open(p, encoding="utf-8"))

def find_list(data):
    if isinstance(data, list): return data
    for v in data.values():
        if isinstance(v, list): return v
    return None

checks = {
 "Hanahuac/Resources/countries.json": ["name_it","capital_it"],
 "Hanahuac/Resources/rivers.json": ["name_it"],
 "Hanahuac/Resources/mountains.json": ["name_it"],
 "Hanahuac/Resources/seas.json": ["name_it"],
}
total_problems = 0
for path, fields in checks.items():
    data = load(path)
    items = find_list(data)
    n = len(items)
    for f in fields:
        missing = [it.get("name_en") or it.get("name") or it.get("id") or "?" for it in items if not it.get(f) or not str(it.get(f)).strip()]
        print(f"{path}: {n} items, missing '{f}': {len(missing)}")
        if missing:
            total_problems += len(missing)
            print("   ", missing[:20])
print("TOTAL MISSING:", total_problems)
